// Independent development-only IEEE set-query oracle, never installed.
using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;
[assembly:System.Runtime.Versioning.TargetFramework(".NETFramework,Version=v4.7.2")]
class Reference {
 static T[] Query<T>(int m,int policy,T[] a,T[] b){IEqualityComparer<T> c=policy==1?null:EqualityComparer<T>.Default;return (m==0?(policy==0?a.Distinct():a.Distinct(c)):m==1?(policy==0?a.Union(b):a.Union(b,c)):m==2?(policy==0?a.Intersect(b):a.Intersect(b,c)):(policy==0?a.Except(b):a.Except(b,c))).ToArray();}
 static float F(uint b){return BitConverter.ToSingle(BitConverter.GetBytes(b),0);}static double D(ulong b){return BitConverter.Int64BitsToDouble(unchecked((long)b));}static string FH(float f){return BitConverter.ToUInt32(BitConverter.GetBytes(f),0).ToString("x8");}static string DH(double d){return unchecked((ulong)BitConverter.DoubleToInt64Bits(d)).ToString("x16");}static string S<T>(T[] a,Func<T,string> h){return a.Length==0?"-":string.Join(",",a.Select(h));}
 public static void Main(string[] args){using(var output=new StreamWriter(args[0],false,new UTF8Encoding(false))){output.WriteLine("# Independent Framework CLR "+Environment.Version+" Single/Double lazy set queries with exact IEEE input and output bits");var fb=new uint[]{0,0x80000000U,0x7fc00001U,0x7fc00002U,0x7f800001U,0xffc00002U,0x7f800000U,0xff800000U,0x3f800000U,0xbf800000U,0x3f000000U};var db=new ulong[]{0,0x8000000000000000UL,0x7ff8000000000001UL,0x7ff8000000000002UL,0x7ff0000000000001UL,0xfff8000000000002UL,0x7ff0000000000000UL,0xfff0000000000000UL,0x3ff0000000000000UL,0xbff0000000000000UL,0x3fe0000000000000UL};for(int m=0;m<4;++m)for(int policy=0;policy<3;++policy)for(int shape=0;shape<4;++shape)for(int second=0;second<(m==0?1:3);++second){var af=shape==0?new uint[0]:shape==1?fb:shape==2?fb.Reverse().ToArray():fb.Concat(fb).ToArray();var ad=shape==0?new ulong[0]:shape==1?db:shape==2?db.Reverse().ToArray():db.Concat(db).ToArray();var bf=second==0?fb.Skip(1).Concat(fb.Take(1)).ToArray():second==1?new uint[0]:new uint[]{0x80000000U,0x7fc00002U,0x7f800001U};var bd=second==0?db.Skip(1).Concat(db.Take(1)).ToArray():second==1?new ulong[0]:new ulong[]{0x8000000000000000UL,0x7ff8000000000002UL,0x7ff0000000000001UL};var a=Array.ConvertAll(af,F);var b=Array.ConvertAll(bf,F);var x=Query(m,policy,a,b);output.WriteLine("single\t"+m+"\t"+policy+"\t"+S(a,FH)+"\t"+S(b,FH)+"\t"+S(x,FH));var da=Array.ConvertAll(ad,D);var dd=Array.ConvertAll(bd,D);var dx=Query(m,policy,da,dd);output.WriteLine("real\t"+m+"\t"+policy+"\t"+S(da,DH)+"\t"+S(dd,DH)+"\t"+S(dx,DH));}}}
}
